<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanban Board</title>
<style>
  :root{
    --bg:#0f1220;
    --bg-2:#151a2e;
    --panel:#1b2138;
    --panel-2:#212948;
    --card:#262f52;
    --text:#e8ebf6;
    --muted:#9aa3c4;
    --line:#2e3860;
    --accent:#6d8bff;
    --todo:#6d8bff;
    --doing:#f5a524;
    --done:#2fd07a;
    --danger:#ff6b6b;
    --radius:14px;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    background:radial-gradient(1200px 700px at 15% -10%,#1d2542 0%,var(--bg) 55%) fixed;
    color:var(--text);
    -webkit-font-smoothing:antialiased;
  }
  .wrap{max-width:1180px;margin:0 auto;padding:32px 20px 64px}
  header.top{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin-bottom:22px}
  h1{font-size:22px;margin:0;letter-spacing:.2px;font-weight:650}
  h1 span{color:var(--muted);font-weight:400;font-size:14px;margin-left:10px}
  .composer{display:flex;gap:10px;margin-left:auto;flex:1 1 340px;max-width:520px}
  #new-card{
    flex:1;min-width:0;padding:11px 14px;border-radius:10px;
    border:1px solid var(--line);background:var(--panel);color:var(--text);
    font-size:14px;outline:none;transition:border-color .15s,box-shadow .15s;
  }
  #new-card::placeholder{color:#7c86ab}
  #new-card:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(109,139,255,.18)}
  #add-card{
    padding:11px 18px;border-radius:10px;border:1px solid transparent;
    background:linear-gradient(180deg,#7b96ff,#5b79f0);color:#fff;
    font-size:14px;font-weight:600;cursor:pointer;white-space:nowrap;
    transition:transform .08s,filter .15s;
  }
  #add-card:hover{filter:brightness(1.07)}
  #add-card:active{transform:translateY(1px)}

  .board{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;align-items:start}
  @media (max-width:860px){.board{grid-template-columns:1fr}}

  .column{
    background:linear-gradient(180deg,var(--panel),var(--bg-2));
    border:1px solid var(--line);border-radius:var(--radius);
    padding:14px;min-height:220px;
    transition:border-color .15s,background .15s,box-shadow .15s;
  }
  .column.drag-over{
    border-color:var(--accent);
    box-shadow:0 0 0 3px rgba(109,139,255,.15) inset;
    background:linear-gradient(180deg,var(--panel-2),var(--panel));
  }
  .col-header{display:flex;align-items:center;gap:10px;padding:2px 4px 12px}
  .dot{width:9px;height:9px;border-radius:50%;flex:none}
  #col-todo .dot{background:var(--todo)}
  #col-doing .dot{background:var(--doing)}
  #col-done .dot{background:var(--done)}
  .col-title{font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#cbd3ee}
  .count{
    margin-left:auto;min-width:26px;text-align:center;
    background:#0e1striped;background:#101534;border:1px solid var(--line);
    color:var(--muted);font-size:12px;font-weight:700;
    padding:3px 9px;border-radius:999px;
  }
  .cards{display:flex;flex-direction:column;gap:10px;min-height:70px}

  .card{
    display:flex;align-items:flex-start;gap:10px;
    background:linear-gradient(180deg,#2b3459,var(--card));
    border:1px solid #36406c;border-radius:11px;
    padding:12px 12px 12px 14px;
    box-shadow:0 1px 0 rgba(255,255,255,.04) inset,0 6px 16px rgba(0,0,0,.25);
    cursor:grab;user-select:none;
    transition:transform .1s,box-shadow .15s,border-color .15s;
  }
  .card:hover{border-color:#4b57ا;border-color:#4b5798;transform:translateY(-1px)}
  .card:active{cursor:grabbing}
  .card.dragging{opacity:.45;transform:rotate(1.5deg) scale(.99)}
  .card-title{flex:1;font-size:14.5px;line-height:1.4;word-break:break-word}
  .card-del{
    flex:none;width:24px;height:24px;line-height:1;
    border-radius:7px;border:1px solid transparent;background:transparent;
    color:var(--muted);font-size:16px;cursor:pointer;
    display:grid;place-items:center;
    transition:background .15s,color .15s,border-color .15s;
  }
  .card-del:hover{background:rgba(255,107,107,.14);color:var(--danger);border-color:rgba(255,107,107,.35)}

  .empty{
    border:1.5px dashed #333d68;border-radius:10px;
    color:#6f79a1;font-size:12.5px;text-align:center;padding:16px 8px;
  }
</style>
</head>
<body>
<div class="wrap">
  <header class="top">
    <h1>Kanban<span>drag cards between columns</span></h1>
    <div class="composer">
      <input id="new-card" type="text" placeholder="Add a task…" autocomplete="off">
      <button id="add-card" type="button">Add</button>
    </div>
  </header>

  <main class="board">
    <section class="column" id="col-todo">
      <div class="col-header"><i class="dot"></i><span class="col-title">To Do</span><span class="count">0</span></div>
      <div class="cards"></div>
    </section>
    <section class="column" id="col-doing">
      <div class="col-header"><i class="dot"></i><span class="col-title">Doing</span><span class="count">0</span></div>
      <div class="cards"></div>
    </section>
    <section class="column" id="col-done">
      <div class="col-header"><i class="dot"></i><span class="col-title">Done</span><span class="count">0</span></div>
      <div class="cards"></div>
    </section>
  </main>
</div>

<script>
(function () {
  var STORAGE_KEY = 'kanban.board.v1';
  var COLUMNS = ['todo', 'doing', 'done'];

  var state = load();
  var nextId = state.reduce(function (m, c) { return Math.max(m, c.id); }, 0) + 1;

  var input = document.getElementById('new-card');
  var addBtn = document.getElementById('add-card');

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var data = JSON.parse(raw);
      if (!Array.isArray(data)) return [];
      return data
        .filter(function (c) { return c && typeof c.title === 'string' && COLUMNS.indexOf(c.col) !== -1; })
        .map(function (c, i) {
          return { id: Number(c.id) > 0 ? Number(c.id) : i + 1, title: c.title, col: c.col };
        });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) {}
  }

  function cardsHost(col) {
    return document.querySelector('#col-' + col + ' .cards');
  }

  function makeCard(card) {
    var el = document.createElement('div');
    el.className = 'card';
    el.setAttribute('draggable', 'true');
    el.dataset.id = String(card.id);

    var title = document.createElement('div');
    title.className = 'card-title';
    title.textContent = card.title;

    var del = document.createElement('button');
    del.className = 'card-del';
    del.type = 'button';
    del.title = 'Delete card';
    del.setAttribute('aria-label', 'Delete card');
    del.textContent = '×';
    del.addEventListener('click', function (e) {
      e.stopPropagation();
      removeCard(card.id);
    });

    el.addEventListener('dragstart', function (e) {
      el.classList.add('dragging');
      if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = 'move';
        try { e.dataTransfer.setData('text/plain', String(card.id)); } catch (err) {}
      }
    });
    el.addEventListener('dragend', function () {
      el.classList.remove('dragging');
      COLUMNS.forEach(function (c) {
        document.getElementById('col-' + c).classList.remove('drag-over');
      });
    });

    el.appendChild(title);
    el.appendChild(del);
    return el;
  }

  function render() {
    COLUMNS.forEach(function (col) {
      var host = cardsHost(col);
      host.innerHTML = '';
      var items = state.filter(function (c) { return c.col === col; });
      items.forEach(function (c) { host.appendChild(makeCard(c)); });
      if (items.length === 0) {
        var ph = document.createElement('div');
        ph.className = 'empty';
        ph.textContent = 'Drop cards here';
        host.appendChild(ph);
      }
      document.querySelector('#col-' + col + ' .count').textContent = String(items.length);
    });
  }

  function addCard(title) {
    var t = String(title == null ? '' : title).trim();
    if (!t) return false;
    state.push({ id: nextId++, title: t, col: 'todo' });
    save();
    render();
    return true;
  }

  function removeCard(id) {
    state = state.filter(function (c) { return c.id !== id; });
    save();
    render();
  }

  function moveCard(id, col) {
    if (COLUMNS.indexOf(col) === -1) return;
    var moved = false;
    state.forEach(function (c) {
      if (c.id === id && c.col !== col) { c.col = col; moved = true; }
    });
    if (moved) { save(); render(); }
  }

  addBtn.addEventListener('click', function () {
    if (addCard(input.value)) input.value = '';
    input.focus();
  });

  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (addCard(input.value)) input.value = '';
    }
  });

  COLUMNS.forEach(function (col) {
    var zone = document.getElementById('col-' + col);

    zone.addEventListener('dragover', function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = 'move';
      zone.classList.add('drag-over');
    });

    zone.addEventListener('dragenter', function (e) {
      e.preventDefault();
      zone.classList.add('drag-over');
    });

    zone.addEventListener('dragleave', function (e) {
      if (!zone.contains(e.relatedTarget)) zone.classList.remove('drag-over');
    });

    zone.addEventListener('drop', function (e) {
      e.preventDefault();
      e.stopPropagation();
      zone.classList.remove('drag-over');
      var id = null;
      if (e.dataTransfer) {
        var raw = '';
        try { raw = e.dataTransfer.getData('text/plain'); } catch (err) {}
        if (raw !== '' && !isNaN(Number(raw))) id = Number(raw);
      }
      if (id === null) {
        var dragging = document.querySelector('.card.dragging');
        if (dragging) id = Number(dragging.dataset.id);
      }
      if (id !== null) moveCard(id, col);
    });
  });

  render();
})();
</script>
</body>
</html>
